### 0.1 探测脚本 `tools/probe_pipeline.py`

```python
#!/usr/bin/env python3
"""探测工程渲染管线/导入路径/资产格式/单位约定，输出 out/pipeline.json"""
import json, sys, fnmatch
from pathlib import Path

ROOT = Path(sys.argv[1] if len(sys.argv) > 1 else '.').resolve()
OUT  = ROOT / 'out'; OUT.mkdir(exist_ok=True)

ENGINE_MARKERS = {
    'unity':       ['ProjectSettings/ProjectVersion.txt'],
    'unreal':      ['*.uproject'],
    'godot':       ['project.godot'],
    'web-three':   ['package.json'],      # 进一步看依赖里是否有 three
    'web-babylon': ['package.json'],
    'blender':     ['*.blend'],
}
ASSET_EXT = {'.glb', '.gltf', '.fbx', '.obj', '.dae', '.usd', '.usda', '.usdc'}
SRC_EXT   = {'.blend', '.ma', '.mb', '.max', '.c4d', '.zpr', '.ztl', '.fbx'}

def glob_any(pat):
    return [p for p in ROOT.rglob(pat.split('/')[-1]) if fnmatch.fnmatch(str(p.relative_to(ROOT)), pat)]

def detect_engine():
    hits = {}
    for eng, pats in ENGINE_MARKERS.items():
        found = []
        for pat in pats:
            found += glob_any(pat)
        if found:
            hits[eng] = [str(p.relative_to(ROOT)) for p in found[:5]]
    # package.json 依赖细分
    for pkg in (ROOT / 'package.json', ROOT / 'app' / 'package.json'):
        if pkg.exists():
            deps = json.loads(pkg.read_text()).get('dependencies', {})
            if 'three' in deps:   hits.setdefault('web-three', []).append(str(pkg.relative_to(ROOT)))
            if '@babylonjs/core' in deps: hits.setdefault('web-babylon', []).append(str(pkg.relative_to(ROOT)))
    return hits

def scan_assets():
    assets, sources = [], []
    for p in ROOT.rglob('*'):
        if not p.is_file() or any(s in p.parts for s in ('.git', 'node_modules', 'Library', 'Temp', 'out')):
            continue
        ext = p.suffix.lower()
        if ext in ASSET_EXT: assets.append(str(p.relative_to(ROOT)))
        elif ext in SRC_EXT: sources.append(str(p.relative_to(ROOT)))
    return assets, sources

def detect_unit_convention():
    """从工程配置里抓单位/轴向；抓不到就标未知。"""
    hints = {}
    for name, keys in {
        'unity':  ['ProjectSettings/ProjectSettings.asset'],
        'godot':  ['project.godot'],
        'unreal': ['Config/DefaultEngine.ini'],
    }.items():
        for rel in keys:
            p = ROOT / rel
            if p.exists():
                t = p.read_text(errors='ignore')
                if 'meter' in t.lower() or 'metre' in t.lower(): hints[name + '.unit'] = 'meter-ish'
    # glTF 导出侧
    for p in ROOT.rglob('*.blend'):
        hints.setdefault('blender_source', str(p.relative_to(ROOT)))
    return hints

def detect_existing_checks():
    pats = ['*normal*', '*audit*', '*validate*', '*lint*mesh*', '*.github/workflows/*']
    found = []
    for p in ROOT.rglob('*'):
        if p.is_file() and any(k in p.name.lower() for k in ('normal', 'audit', 'validate')):
            if p.suffix in {'.py', '.js', '.ts', '.sh', '.yml', '.yaml'}:
                found.append(str(p.relative_to(ROOT)))
    return found[:20]

result = {
    'root': str(ROOT),
    'engine_markers': detect_engine(),
    'unit_hints': detect_unit_convention(),
    'existing_checks': detect_existing_checks(),
    'assets': scan_assets()[0][:500],
    'sources': scan_assets()[1][:200],
    'asset_ext_histogram': {},
}
for a in result['assets']:
    e = Path(a).suffix.lower()
    result['asset_ext_histogram'][e] = result['asset_ext_histogram'].get(e, 0) + 1

(OUT / 'pipeline.json').write_text(json.dumps(result, indent=2, ensure_ascii=False))
