import numpy as np

EPS = 1e-20

# ---------- 几何基础 ----------
def face_geom_normals(V, F):
    """按顶点绕序算几何面法线（Newell 的三角退化版）。"""
    tri = V[F]
    n = np.cross(tri[:, 1] - tri[:, 0], tri[:, 2] - tri[:, 0])
    ln = np.linalg.norm(n, axis=1, keepdims=True)
    return n / np.where(ln > EPS, ln, 1.0)

def face_areas(V, F):
    tri = V[F]
    return 0.5 * np.linalg.norm(np.cross(tri[:, 1] - tri[:, 0], tri[:, 2] - tri[:, 0]), axis=1)

def signed_volume(V, F):
    tri = V[F]
    return float(np.einsum('ij,ij->i', tri[:, 0], np.cross(tri[:, 1], tri[:, 2])).sum() / 6.0)

def back_face_ratio(V, F, gn=None):
    """以网格质心为观察原点，统计几何法线背向观察者的面占比。"""
    if gn is None: gn = face_geom_normals(V, F)
    c   = V[F].mean(axis=1)
    ctr = V.mean(axis=0)
    view = c - ctr
    ln = np.linalg.norm(view, axis=1, keepdims=True)
    view = view / np.where(ln > 1e-12, ln, 1.0)          # 退化面（零面积）视作朝前
