    {
        Vector3 origin = rb.position + Vector3.up * rayStartHeight;
        if (Physics.Raycast(origin, Vector3.down, out hit, rayStartHeight + rayLength, groundMask, QueryTriggerInteraction.Ignore))
        {
            if (Vector3.Angle(Vector3.up, hit.normal) > maxSlopeAngle)
                return false;

            groundNormal = hit.normal;
            float currentHeight = hit.distance - rayStartHeight;
            return currentHeight <= maxGroundDistance;
        }
        return false;
    }

    void ApplyLift()
    {
        float currentHeight = hit.distance - rayStartHeight;

        if (onlyLiftWhenTooLow && currentHeight >= minGroundDistance)
            return;

        float error = Mathf.Max(0f, minGroundDistance - currentHeight);
        Vector3 pointVel = rb.GetPointVelocity(hit.point);
        float verticalVel = Vector3.Dot(pointVel, Vector3.up);

        float force = error * liftSpring - verticalVel * liftDamper;
        force = Mathf.Clamp(force, 0f, maxLiftForce);
        rb.AddForce(Vector3.up * force, ForceMode.Force);
    }

    void ApplyAlign()
    {
        Vector3 currentUp = rb.rotation * Vector3.up;
        Quaternion targetRot = Quaternion.FromToRotation(currentUp, groundNormal) * rb.rotation;
        Quaternion delta = targetRot * Quaternion.Inverse(rb.rotation);

        delta.ToAngleAxis(out float angle, out Vector3 axis);
        if (angle > 180f) angle -= 360f;
        if (Mathf.Abs(angle) < 0.01f || axis.sqrMagnitude < 0.001f)
            return;

        axis.Normalize();
        float angularVel = Vector3.Dot(rb.angularVelocity, axis);
        float torque = angle * Mathf.Deg2Rad * alignSpring - angularVel * alignDamper;

        Vector3 torqueVec = axis * torque;
        torqueVec = Vector3.ClampMagnitude(torqueVec, maxAlignTorque);
        rb.AddTorque(torqueVec, ForceMode.Force);
    }

    void ApplyAntiSlip()
    {
        Vector3 gravitySlope = Vector3.ProjectOnPlane(Physics.gravity, groundNormal);
        Vector3 antiForce = -gravitySlope * rb.mass * antiSlipGrip;
        antiForce = Vector3.ClampMagnitude(antiForce, maxAntiSlipForce);
        rb.AddForce(antiForce, ForceMode.Force);
    }
}
```

调整时重点看这几个：
- `groundMask` 只勾地面层。
- `rayStartHeight` 设成车身中心到车顶附近。
- `minGroundDistance` 设成正常离地距离减 `0.1`。
- 如果还抖，`Fixed Timestep` 改 `0.005`，并把 `WheelCollider` 所有操作都放在 `FixedUpdate` 里。
- 如果不想坦克完全贴斜坡，把 `alignToSlope` 关掉。

